static int camif_request_irqs ( struct platform_device * pdev , struct camif_dev * camif ) { int irq , ret , i ; for ( i = 0 ; i < CAMIF_VP_NUM ; i ++ ) { struct camif_vp * vp = & camif -> vp [ i ] ; init_waitqueue_head ( & vp -> irq_queue ) ; irq = platform_get_irq ( pdev , i ) ; if ( irq <= 0 ) { dev_err ( & pdev -> dev , "failed to get IRQ %d\n" , i ) ; return - ENXIO ; } if ( ret < 0 ) { dev_err ( & pdev -> dev , "failed to install IRQ: %d\n" , ret ) ; break ; } } return ret ; } 